contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 rate, uint256 duration) public payable {
        uint256 actual = c.interestFor(amount, rate, duration); if (__ESBMC_reverted()) return;
        uint256 expected = (amount * ((rate * duration) / 365 days)) / 1e18;
        assert(actual == expected);
    }

    receive() external payable {}
}

