pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 rate, uint256 duration) internal {
        uint256 actual;
        try c.interestFor(amount, rate, duration) returns (uint256 __r) { actual = __r; } catch { return; }
        uint256 expected = (amount * ((rate * duration) / 365 days)) / 1e18;
        assertTrue(actual == expected);
    }

    function testFuzz_run(uint256 amount, uint256 rate, uint256 duration) public {
        _run(amount, rate, duration);
    }

    receive() external payable {}
}
